class Solution {
public:
    int sumSubseqWidths(vector<int>& nums) {
        const long long MOD = 1000000007;
        const long long inv2 = 500000004;
        int n = nums.size();
        sort(nums.begin(), nums.end());
        // Compute 2^(n-1) mod MOD via fast exponentiation
        long long p2_bwd = 1;
        int e = n - 1;
        long long b = 2;
        while (e > 0) {
            if (e & 1) p2_bwd = p2_bwd * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        long long p2_fwd = 1;
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            long long contrib = (p2_fwd - p2_bwd + MOD) % MOD;
            ans = (ans + (long long)nums[i] * contrib) % MOD;
            p2_fwd = p2_fwd * 2 % MOD;
            p2_bwd = p2_bwd * inv2 % MOD;
        }
        return (int)ans;
    }
};
